import { Box, Card, CardContent, Grid, Typography } from "@mui/material";
import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import FallbackSpinner from "src/@core/components/spinner";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { toastError } from "src/utils/utils";

const data = [
  {
    stats: "0",
    title: "IT Solutions",
    //type: "usersCount",
    link: "/it-solutions",
  },

  {
    stats: "0",
    title: "Success Stories",
    link: "/success-stories",
  },
  {
    stats: "0",
    title: "Client Category",
    link: "/client-category",
  },
  {
    stats: "0",
    title: "Career",
    link: "/career",
  },
  {
    stats: "0",
    title: "Blogs",
    link: "/blog",
  },
];
function DashBoardPage() {
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = React.useState(data);
  const fetchData = () => {
    setLoading(true);

    axiosInstance
      .get(ApiEndPoints.DASHBOARD.count)
      .then((response) => {
        // let data = response?.data?.stats;
        // setStats((prev) =>
        //   prev.map((p) => ({
        //     ...p,
        //     ...(data[`${p.type}`] && { stats: data[`${p.type}`] }),
        //   }))
        // );
        console.log(response.data);
        const responseData = response.data;
        if (responseData) {
          const updatedStats = stats.map((item) => {
            switch (item.title) {
              case "IT Solutions":
                return { ...item, stats: responseData.it_solution_count };
              case "Success Stories":
                return { ...item, stats: responseData.success_stories_count };
              case "Client Category":
                return { ...item, stats: responseData.client_catagory_count };
              case "Career":
                return { ...item, stats: responseData.career_count };
              case "Blogs":
                return { ...item, stats: responseData.Blog_count };
              default:
                return item;
            }
          });

          setStats(updatedStats);
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  console.log(stats);

  useEffect(() => {
    fetchData();
  }, []);
  if (loading) {
    return <FallbackSpinner />;
  }
  return (
    <>
      <Grid container spacing={6} height={100}>
        {stats.map((item, index) => (
          <Grid key={index} item xs={12} sm={4}>
            <Typography
              component={Link}
              to={item.link}
              key={index}
              variant="body1"
              sx={{ textDecoration: "none" }}
            >
              <Card
                sx={{
                  overflow: "visible",
                  position: "relative",
                  border: "1px solid #5B2E1E",
                  backgroundImage: `url('/assets/images/logo.png')`,
                  backgroundRepeat: "no-repeat",
                  backgroundPosition: "bottom right",
                }}
              >
                <CardContent
                  sx={{ display: "flex", flexDirection: "column", gap: 10 }}
                >
                  <Typography sx={{ fontWeight: 600 }}>{item.title}</Typography>
                  <Box>
                    <Typography key={index} variant="h5">
                      {item?.stats}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Typography>
          </Grid>
        ))}
      </Grid>
    </>
  );
}

export default DashBoardPage;
